import "server-only";

import PostHogClient from "@/lib/posthog";

/** Existing PostHog feature flag used as the tutor-orientation kill switch. */
export const TUTOR_ORIENTATION_FLAG = "tutor-orientation";

// Deduplicate the proxy/layout checks generated by one navigation while keeping
// emergency flag changes responsive. Each server instance refreshes within 2s.
export const TUTOR_ORIENTATION_FLAG_CACHE_TTL_MS = 2_000;

const tutorFlagCache = new Map<string, { expiresAt: number; result: Promise<boolean> }>();
const MAX_TUTOR_FLAG_CACHE_ENTRIES = 10_000;

export const canViewTutorOrientation = (role: string | null | undefined) =>
  role === "Tutor" || role === "Admin";

type OrientationProfile = {
  id?: string | null;
  email?: string | null;
  role?: string | null;
};

/**
 * Whether this profile can open the tutor orientation.
 * Admins retain preview access. Tutor access and enforcement follow PostHog, with
 * failures treated as disabled so the flag remains a safe emergency kill switch.
 */
export async function hasTutorOrientationAccess(
  profile: OrientationProfile | null | undefined,
): Promise<boolean> {
  if (!profile || !canViewTutorOrientation(profile.role)) return false;
  if (profile.role === "Admin") return true;
  if (!profile.id) return false;

  const client = PostHogClient();
  if (!client) return false;

  const cacheKey = `${profile.id}:${profile.email ?? ""}`;
  const now = Date.now();
  const cached = tutorFlagCache.get(cacheKey);
  if (cached && cached.expiresAt > now) return cached.result;
  if (cached) tutorFlagCache.delete(cacheKey);

  if (tutorFlagCache.size >= MAX_TUTOR_FLAG_CACHE_ENTRIES) tutorFlagCache.clear();

  const result = client
    .evaluateFlags(profile.id, {
      flagKeys: [TUTOR_ORIENTATION_FLAG],
      personProperties: {
        ...(profile.email ? { email: profile.email } : {}),
        role: "Tutor",
      },
    })
    .then((flags) => flags.isEnabled(TUTOR_ORIENTATION_FLAG))
    .catch((error) => {
      console.error("Failed to evaluate tutor orientation flag:", error);
      return false;
    });

  tutorFlagCache.set(cacheKey, {
    expiresAt: now + TUTOR_ORIENTATION_FLAG_CACHE_TTL_MS,
    result,
  });
  return result;
}
